	/** 
	 * jumpstart the process by instantiating2 Timesheet
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		timesheetId = TimesheetService.getTimesheetInstance()
		.createTimesheet( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		TimesheetService.getTimesheetInstance()
				.createTimesheet( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.timesheetSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Timesheet : " + successValue.getTimesheetId());
							  if (successValue.getTimesheetId().equals(timesheetId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfTimesheetList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Timesheet test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on timesheet consumed")
					);
			subscriber.timesheetSubscribe( timesheetId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Timesheet : " + successValue.getTimesheetId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfTimesheetList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on timesheet for timesheetId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Timesheet. 
	 */
	protected Timesheet read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Timesheet" );

		Timesheet entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Timesheet with primary key" );
		msg.append( timesheetId );
		
		TimesheetFetchOneSummary fetchOneSummary = new TimesheetFetchOneSummary( timesheetId );

		try {
			entity = TimesheetService.getTimesheetInstance().getTimesheet( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Timesheet " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Timesheet.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Timesheet." );

		StringBuilder msg = new StringBuilder( "Failed to update a Timesheet : " );        
		Timesheet entity = read();
		UpdateTimesheetCommand command = generateUpdateCommand();
		command.setTimesheetId(entity.getTimesheetId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Timesheet." );

			// for use later on...
			timesheetId = entity.getTimesheetId();

			TimesheetService proxy = TimesheetService.getTimesheetInstance();  

			proxy.updateTimesheet( command ).get();

			LOGGER.info( "-- Successfully saved Timesheet - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + timesheetId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Timesheet.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Timesheet." );

		Timesheet entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Timesheet with id " + timesheetId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Timesheet with id " + timesheetId );

			throw e;
		}

		try{
			TimesheetService.getTimesheetInstance().delete( new DeleteTimesheetCommand( entity.getTimesheetId() ) ).get();
			LOGGER.info( "-- Successfully deleted Timesheet with id " + timesheetId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Timesheet with id " + timesheetId );

			throw e;
		}
	}

	/**
	 * get all Timesheets.
	 */
	protected List<Timesheet> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Timesheets:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Timesheet : " );        
		List<Timesheet> collection  = new ArrayList<>();

		try {
			// call the static get method on the TimesheetService
			collection = TimesheetService.getTimesheetInstance().getAllTimesheet();
			assertNotNull( collection, "An Empty collection of Timesheet was incorrectly returned.");
			
			// Now print out the values
			Timesheet entity = null;            
			Iterator<Timesheet> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getTimesheetId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

